(function(root,factory){const api=factory();if(typeof module==='object'&&module.exports)module.exports=api;else root.WHYDrafts=api;})(typeof globalThis!=='undefined'?globalThis:this,function(){'use strict';
const fields={aspiration:['text'],plan:['title','reason','when','where','amount','prediction','observe','stop'],experience:['actual','observed','feeling','interpretation','insight','unknown','next','planId']};
const clone=x=>JSON.parse(JSON.stringify(x));const key=()=> 'd-'+Date.now().toString(36)+'-'+Math.random().toString(36).slice(2,10);
function validate(d){if(!d||!fields[d.kind]||!['candidate','held','adopted','deleted','stale'].includes(d.status)||typeof d.id!=='string'||typeof d.createdAt!=='string'||!Number.isFinite(Date.parse(d.createdAt))||typeof d.origin!=='string'||!Array.isArray(d.evidence)||d.evidence.length>20||!Array.isArray(d.reviewedFields)||d.reviewedFields.some(k=>!fields[d.kind].includes(k))||!(d.recordId===null||typeof d.recordId==='string')||!(d.conversationId===null||typeof d.conversationId==='string'))throw Error('候補の形式が不正です');if(Object.keys(d).sort().join()!==['id','createdAt','kind','status','values','evidence','origin','reviewedFields','recordId','conversationId'].sort().join())throw Error('候補に未対応の項目があります');if(Object.keys(d.values).sort().join()!==fields[d.kind].slice().sort().join()||Object.values(d.values).some(v=>typeof v!=='string'||v.length>2000))throw Error('候補の本文が不正です');for(const e of d.evidence)if(Object.keys(e).sort().join()!==['messageId','quote','role'].sort().join()||e.role!=='user'||typeof e.messageId!=='string'||typeof e.quote!=='string'||e.quote.length>2000)throw Error('候補の出典が不正です');return clone(d)}
function parts(kind,live,ids){if(!fields[kind])throw Error('候補の種類が不正です');const msgs=(live?.messages||[]).filter(m=>ids.includes(m.id)&&m.role==='user'&&m.status==='current'),type=kind==='aspiration'?'value':kind==='experience'?'experience':null,result=[];function add(m,quote,origin){if(typeof quote!=='string'||!quote.trim()||quote.length>2000||!m.text.includes(quote)||result.some(x=>x.messageId===m.id&&x.quote===quote))return;result.push({messageId:m.id,quote,origin})}for(const m of msgs){for(const o of live.observations||[])if(type&&o.kind===type)add(m,o.quote,'ai-classification-unconfirmed');for(const quote of m.text.match(/[^。！？\n]+[。！？]?/g)||[])add(m,quote.trim(),'person-selected-passage')}return result;}
function create(kind,live,ids,{reuseAllowed=false,planId='',part=null}={}){if(!reuseAllowed)throw Error('会話を再利用する許可が必要です');if(!fields[kind])throw Error('候補の種類が不正です');const selected=(live?.messages||[]).filter(m=>ids.includes(m.id)&&m.role==='user'&&m.status==='current');if(!selected.length||selected.length>20)throw Error('自分の発言を選んでください');const all=selected.map(m=>m.text).join('\n'),latest=selected.at(-1).text;let values=Object.fromEntries(fields[kind].map(k=>[k,''])),origin='person-selected-quotation';
if(kind==='aspiration'||kind==='experience'){const candidates=parts(kind,live,ids),ai=candidates.filter(x=>x.origin==='ai-classification-unconfirmed');const chosen=part|| (ai.length===1?ai[0]:null);if(!chosen||!candidates.some(x=>x.messageId===chosen.messageId&&x.quote===chosen.quote))throw Error('残す部分を選んでください');const verified=candidates.find(x=>x.messageId===chosen.messageId&&x.quote===chosen.quote);origin=verified.origin;values[kind==='aspiration'?'text':'actual']=verified.quote;part=verified;}
if(kind==='plan'){values.title=(live.actionCandidate||latest).slice(0,2000);if(live.actionCandidate)origin='ai-action-unselected';values.when=all.match(/仕事から帰って|帰宅後|夕食の前|夕食前|朝食後|週末|明日|今日|毎朝|週[0-9０-９]+回/)?.[0]||'';values.amount=all.match(/[0-9０-９]+分(?:だけ|程度|を目安)?/)?.[0]||'';const reason=all.match(/(?:理由は|なぜなら)([^。\n]+)/);values.reason=reason?.[1]||'';}
if(kind==='experience'){values.planId=planId;}
return validate({id:key(),createdAt:new Date().toISOString(),kind,status:'candidate',values,evidence:part?[{messageId:part.messageId,quote:part.quote,role:'user'}]:selected.map(m=>({messageId:m.id,quote:m.text.slice(0,2000),role:'user'})),origin,reviewedFields:[],recordId:null,conversationId:live.conversationId||null});}
function isCurrent(d,live){return !!live&&d.conversationId===live.conversationId&&d.evidence.every(e=>live.messages.some(m=>m.id===e.messageId&&m.role==='user'&&m.status==='current'&&m.text.includes(e.quote)));}
function select(d,{confirmed=false,status='selected'}={}){validate(d);if(!confirmed)throw Error('内容を本人が確認してください');if(['stale','deleted'].includes(d.status))throw Error('訂正前または削除済みの候補は採用できません');const required=d.kind==='aspiration'?'text':d.kind==='plan'?'title':'actual';if(!d.values[required].trim())throw Error('残す言葉を記入してください');if(d.kind==='plan'&&!['draft','selected','held','paused','completed'].includes(status))throw Error('計画の状態が不正です');return{kind:d.kind,values:clone(d.values),status:d.kind==='aspiration'?'confirmed':status,reviewedFields:fields[d.kind].slice()};}
return{fields,parts,create,validate,isCurrent,select};});
